/* \u5B8C\u6574\u5DE5\u4F5C\u533A\u94FA\u6EE1\u5BBF\u4E3B\u5185\u5BB9\u533A\uFF1B280\u2013360px \u4EC5\u7528\u4E8E workspace-sidebar\u3002 */
